#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "gramschmidt.h"

void init_array(
    int m,
    int n,
    double A[20][30],
    double R[30][30],
    double Q[20][30]) {
    int i, j;

    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++) {
            A[i][j] = (((double)((i * j) % m) / m) * 100) + 10;
            Q[i][j] = 0.0;
        }
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            R[i][j] = 0.0;
}

